script:
param {
    alias a
    name "Drive"
    min 0.1
    max 4.0
}

stage {
    y tanh(x * a)
}

param { alias a name "Threshold" min 0.1 max 1.0 }
param { alias b name "Drive" min 0.5 max 6.0 }
stage {
    y hardclip(x * b, a)
}

param { alias a name "Drive" min 0.2 max 5.0 }
param { alias b name "Bias" min 0.0 max 0.3 }
param { alias c name "Offset" min 0.0 max 0.2 }
stage {
    y tanh(x * a + b) - c
}

param { alias a name "Fuzz" min 1.0 max 12.0 }
param { alias b name "Tone" min 400.0 max 8000.0 }
param { alias c name "Bias" min -0.4 max 0.4 }
stage {
    y hardclip((x + c) * a, 0.6)
}
filter {
    type lowpass
    cutoff b
    resonance 0.7
}

param { alias a name "Bits" min 2.0 max 16.0 }
param { alias b name "Rate" min 200.0 max 8000.0 }
param { alias d name "Drive" min 0.5 max 3.0 }
osc {
    name osc1
    shape saw
    freq b / sr
    depth 1.0
}
stage {
    y bitcrush(x * d + y_prev * 0.08 * step(0.0, osc1), a)
}

param { alias a name "Drive" min 1.0 max 10.0 }
param { alias b name "FoldMin" min -1.0 max -0.1 }
param { alias c name "FoldMax" min 0.1 max 1.0 }
param { alias d name "Post" min 0.2 max 2.0 }
stage {
    y fold(x * a, b, c) * d
}

param { alias a name "Rate" min 0.2 max 12.0 }
param { alias b name "Depth" min 0.0 max 1.0 }
param { alias d name "Floor" min 0.0 max 1.0 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y x * (d + (1.0 - d) * (1.0 - b + b * (0.5 + 0.5 * osc1)))
}

param { alias a name "Rate" min 0.2 max 8.0 }
param { alias b name "Depth" min 0.0 max 0.95 }
param { alias c name "Feedback" min 0.0 max 0.8 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y x + y_prev * c + osc1 * b * 0.1
}

param { alias a name "Sensitivity" min 0.1 max 4.0 }
param { alias b name "MinCut" min 200.0 max 1200.0 }
param { alias c name "Sweep" min 500.0 max 6000.0 }
param { alias d name "Res" min 0.3 max 2.5 }
env {
    name env1
    mode peak
    attack 5
    release 120
}
filter {
    type bandpass
    center b + env1 * a * c
    width 900
}
stage {
    y x * 1.1
}

param { alias a name "Freq" min 5.0 max 2000.0 }
param { alias b name "Depth" min 0.0 max 1.0 }
param { alias c name "Offset" min 0.0 max 1.0 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y x * (1.0 - b + b * (osc1 + c))
}

param { alias a name "Rate" min 0.1 max 5.0 }
param { alias b name "Depth" min 0.0 max 1.0 }
param { alias c name "Detune" min 0.0 max 0.5 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y tanh((x + y_prev * 0.15) * (1.0 + (osc1 + c) * b * 0.35))
}

param { alias a name "Rate" min 0.1 max 6.0 }
param { alias b name "Depth" min 200.0 max 4000.0 }
param { alias c name "Base" min 80.0 max 1200.0 }
param { alias d name "Feedback" min 0.0 max 0.8 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y x + y_prev * d
}
filter {
    type highpass
    cutoff c + (0.5 + 0.5 * osc1) * b
    resonance 0.9
}

param { alias a name "Rate" min 0.05 max 8.0 }
param { alias b name "MinCut" min 120.0 max 1200.0 }
param { alias c name "Depth" min 400.0 max 10000.0 }
param { alias d name "Res" min 0.3 max 2.0 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
filter {
    type lowpass
    cutoff b + (0.5 + 0.5 * osc1) * c
    resonance d
}

param { alias a name "Floor" min 60.0 max 1200.0 }
param { alias b name "Range" min 300.0 max 9000.0 }
param { alias c name "Attack" min 1.0 max 50.0 }
param { alias d name "Release" min 20.0 max 400.0 }
env {
    name env1
    mode peak
    attack c
    release d
}
filter {
    type highpass
    cutoff a + env1 * b
    resonance 0.7
}

param { alias a name "Vowel" min 0.0 max 1.0 }
param { alias b name "Spread" min 200.0 max 2000.0 }
param { alias c name "Res" min 0.5 max 3.0 }
filter {
    type bandpass
    center 500 + a * 1700
    width b
}
stage {
    y x
}
filter {
    type bandpass
    center 1100 + a * 1900
    width b * 0.7
}

param { alias a name "LowCut" min 120.0 max 500.0 }
param { alias b name "HighCut" min 2500.0 max 5000.0 }
param { alias c name "Drive" min 0.8 max 2.0 }
param { alias d name "Res" min 0.3 max 1.2 }
filter {
    type highpass
    cutoff a
    resonance d
}
filter {
    type lowpass
    cutoff b
    resonance d
}
stage {
    y tanh(x * c)
}

param { alias a name "Threshold" min -36.0 max -3.0 }
param { alias b name "Ratio" min 1.5 max 12.0 }
param { alias c name "Attack" min 1.0 max 30.0 }
param { alias d name "Makeup" min 0.5 max 3.0 }
comp {
    threshold a
    ratio b
    attack c
    release 120
}
stage {
    y x * d
}

param { alias a name "AttackBoost" min 0.0 max 4.0 }
param { alias b name "Sustain" min -1.0 max 1.0 }
param { alias c name "EnvAtk" min 0.5 max 20.0 }
param { alias d name "EnvRel" min 20.0 max 400.0 }
env {
    name env1
    mode peak
    attack c
    release d
}
stage {
    y x * (1.0 + env1 * a + b * (1.0 - env1))
}

param { alias a name "Gate" min 0.01 max 0.5 }
param { alias b name "Threshold" min -30.0 max -6.0 }
param { alias c name "Ratio" min 1.5 max 10.0 }
param { alias d name "Release" min 30.0 max 300.0 }
stage {
    y x * step(a, abs(x))
}
comp {
    threshold b
    ratio c
    attack 5
    release d
}

param { alias a name "Drive" min 0.5 max 8.0 }
param { alias b name "Tone" min 300.0 max 9000.0 }
param { alias d name "Level" min 0.2 max 1.5 }
stage {
    y tanh(abs(x) * a) * d
}
filter {
    type lowpass
    cutoff b
    resonance 0.8
}

param { alias a name "Noise" min 0.0 max 1.0 }
param { alias d name "Blend" min 0.0 max 1.0 }
stage {
    y x * (1.0 - d) + noise(t * sr) * a * d
}

param { alias a name "Feedback" min 0.0 max 0.98 }
param { alias b name "Input" min 0.0 max 1.5 }
param { alias c name "Damp" min 0.0 max 1.0 }
param { alias d name "Mix" min 0.0 max 1.0 }
stage {
    y (x * b) * (1.0 - d) + (x + y_prev * a * (1.0 - c)) * d
}

param { alias a name "Drive" min 0.5 max 6.0 }
param { alias b name "HighFreq" min 1500.0 max 14000.0 }
param { alias c name "Amount" min 0.0 max 1.0 }
filter {
    type highpass
    cutoff b
    resonance 0.8
}
stage {
    y x + tanh(x * a) * c
}
filter {
    type lowpass
    cutoff 18000
    resonance 0.7
}

param { alias a name "Bits" min 3.0 max 12.0 }
param { alias b name "Noise" min 0.0 max 0.4 }
param { alias c name "LP" min 600.0 max 8000.0 }
param { alias d name "Drive" min 0.5 max 4.0 }
stage {
    y bitcrush(tanh(x * d), a) + noise(t * sr * 0.5) * b
}
filter {
    type lowpass
    cutoff c
    resonance 0.8
}

stage {
    y x
}

param { alias a name "Gain" min 0.1 max 4.0 }
param { alias b name "Trim" min 0.1 max 2.0 }
param { alias c name "Soft" min 0.0 max 1.0 }
stage {
    y (x * a * b) * (1.0 - c) + tanh(x * a * b) * c
}

param { alias a name "Drive" min 0.5 max 6.0 }
param { alias b name "Blend" min 0.0 max 1.0 }
param { alias c name "CompThr" min -30.0 max -6.0 }
param { alias d name "CompRatio" min 1.5 max 8.0 }
comp {
    threshold c
    ratio d
    attack 4
    release 120
}
stage {
    y x * (1.0 - b) + tanh(x * a) * b
}

param { alias a name "Rate" min 0.05 max 3.0 }
param { alias b name "Depth" min 0.0 max 1.0 }
param { alias c name "Feedback" min 0.0 max 0.7 }
param { alias d name "Lowpass" min 700.0 max 12000.0 }
osc {
    name osc1
    shape sin
    freq a
    depth 1.0
}
stage {
    y tanh((x + y_prev * c) * (1.0 + osc1 * b * 0.4))
}
filter {
    type lowpass
    cutoff d
    resonance 0.8
}

param { alias a name "Threshold" min 0.01 max 0.6 }
param { alias b name "ReleaseMix" min 0.0 max 1.0 }
param { alias c name "Drive" min 0.5 max 2.5 }
param { alias d name "Output" min 0.5 max 1.8 }
stage {
    y (x * step(a, abs(x))) * (1.0 - b) + (x + y_prev * 0.2) * b
}
stage {
    y tanh(y * c) * d
}
